import { getUsers } from '@/actions/admin/get-users'
import { UsersTable } from '@/components/admin/UsersTable'
import { UsersToolbar } from '@/components/admin/UsersToolbar'
import { UsersPageClient } from '@/components/admin/UsersPageClient'

export default async function AdminUsers() {
    // Fetch users from Clerk
    let users = []
    try {
        users = await getUsers(100) // Fetch up to 100 users
    } catch (error) {
        console.error('Failed to fetch users:', error)
        // Continue with empty array if fetch fails
    }

    return (
        <div className="space-y-6 animate-fadeIn">
            {/* Header */}
            <header>
                <p className="text-[10px] text-accent uppercase font-bold tracking-[0.3em] mb-1">
                    Entity Management
                </p>
                <h1 className="text-4xl font-extrabold tracking-tight mb-2">
                    Quản Lý Đệ Tử
                </h1>
                <p className="text-sm text-muted-foreground">
                    Total Users: <span className="font-semibold text-foreground">{users.length}</span>
                </p>
            </header>

            {/* Toolbar */}
            <UsersPageClient initialUsers={users}>
                <UsersToolbar />
            </UsersPageClient>

            {/* Users Table */}
            <div className="gap-6">
                <UsersTable users={users} />
            </div>
        </div>
    )
}
